css:
.sl-hero-instructor {
  background-color: var(--smartlearn-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  min-height: 80vh;
  display: flex;
  align-items: center;
  padding-block: clamp(3.5rem, 7vw, 6rem);
}
.sl-hero-instructor .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-instructor .sl-text-emphasis {
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-instructor .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-instructor .sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-hero-instructor .sl-bg-card {
  background-color: var(--smartlearn-card-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-instructor .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-instructor .sl-btn-primary:hover,
.sl-hero-instructor .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-instructor .sl-live-pill {
  background-color: color-mix(in srgb, var(--smartlearn-primary) 14%, var(--smartlearn-card-bg));
  color: var(--smartlearn-primary);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-instructor .sl-pulsing-dot {
  width: 8px;
  height: 8px;
  background-color: var(--smartlearn-primary);
}
.sl-hero-instructor .sl-title-tracking {
  letter-spacing: -0.03em;
}
.sl-hero-instructor .sl-underline-accent {
  text-decoration: underline;
  text-decoration-thickness: 4px;
  text-underline-offset: 6px;
}
.sl-hero-instructor .sl-bg-primary-blob {
  width: min(460px, 85vw);
  height: min(460px, 85vw);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent);
  z-index: 0;
}
.sl-hero-instructor .sl-instructor-img {
  max-height: 560px;
  width: auto;
  object-fit: contain;
  mask-image: linear-gradient(to bottom, black 82%, transparent 100%);
  -webkit-mask-image: linear-gradient(to bottom, black 82%, transparent 100%);
}
.sl-hero-instructor .sl-badge-icon {
  width: 40px;
  height: 40px;
  background-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-instructor .sl-badge-icon-sm {
  width: 30px;
  height: 30px;
  background-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
@media (min-width: 768px) {
  .sl-hero-instructor .sl-orbit-badge {
    position: absolute;
    z-index: 3;
  }
  .sl-hero-instructor .sl-badge-1 { top: 14%; inset-inline-start: 0; }
  .sl-hero-instructor .sl-badge-2 { bottom: 22%; inset-inline-end: 0; }
  .sl-hero-instructor .sl-badge-3 { top: 40%; inset-inline-end: 6%; }
}
@media (max-width: 767px) {
  .sl-hero-instructor .sl-badges-layer {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.75rem;
    margin-top: 1.25rem;
  }
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-instructor .sl-pulsing-dot {
    animation: sl-hero-instructor-pulse 1.8s infinite;
  }
  .sl-hero-instructor .sl-orbit-badge {
    transition: transform 0.25s ease;
  }
  .sl-hero-instructor .sl-orbit-badge:hover {
    transform: translateY(-4px);
  }
  .sl-hero-instructor .sl-badge-1 { animation: sl-hero-instructor-float 5s ease-in-out infinite; }
  .sl-hero-instructor .sl-badge-2 { animation: sl-hero-instructor-float 6s ease-in-out infinite 1s; }
  .sl-hero-instructor .sl-badge-3 { animation: sl-hero-instructor-float 4.5s ease-in-out infinite 1.5s; }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-instructor .sl-pulsing-dot,
  .sl-hero-instructor .sl-badge-1,
  .sl-hero-instructor .sl-badge-2,
  .sl-hero-instructor .sl-badge-3 {
    animation: none;
    transition: none;
  }
}
@keyframes sl-hero-instructor-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}
@keyframes sl-hero-instructor-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
